// 南京大学的校徽和毛笔校名（2026-11-04 我给的图，去了白底做成遮罩）：目标学校放在「距考研」那条签条下面和它的详情里。
// 是透明的形状，颜色由页面上（desk.css 的 --goal：白天南大紫、晚上浅紫），所以晚上不发灰；学习台不能从外面加载图片，只能嵌在这里
export const NJU_SHIELD = 'data:image/png;base64,';
export const NJU_WORD = 'data:image/png;base64,';
export const NJU_EN = 'data:image/png;base64,';
// 每一张的宽高比（遮罩按 contain 铺，盒子要按它的比例）
export const NJU_RATIO = { shield: '216 / 275', word: '534 / 182', en: '534 / 31' };
/** 把三张图写成 CSS 变量（desk.css 的 .dk-nju 用） */
export function installNju(el = document.documentElement) {
  el.style.setProperty('--nju-shield', `url("${NJU_SHIELD}")`);
  el.style.setProperty('--nju-word', `url("${NJU_WORD}")`);
  el.style.setProperty('--nju-en', `url("${NJU_EN}")`);
}
